void Solver::bump_var(int var, double coeff) {
    const double ACT_LIMIT   = 1e100;
    const double VARINC_LIMIT = 1e90;
    const double RESCALE_FACTOR = 1e-100;

    // increase activity of the variable
    double inc = var_inc * coeff;
    activity[var] += inc;

    // if activity overflowed or var_inc is too large, rescale everything once
    if (activity[var] > ACT_LIMIT || var_inc > VARINC_LIMIT) {
        for (int i = 1; i <= vars; ++i) activity[i] *= RESCALE_FACTOR;
        var_inc *= RESCALE_FACTOR;
    }

    // keep VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) vsids.update(var);
}
